//! The client's talent art ids: the icon of each trait spell and the layout of the Legacy
//! trees, generated by scripts/talent-art.mjs into companion/data/talent-art.json.

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(Deserialize)]
pub struct LegacyNode {
    pub id: u32,
    pub col: u32,
    pub row: u32,
    pub spell: u32,
    pub name: String,
    pub max: u32,
    pub icon: u32,
    pub placeholder: bool,
}

#[derive(Deserialize)]
pub struct LegacyTree {
    pub id: u32,
    pub nodes: Vec<LegacyNode>,
    pub edges: Vec<(u32, u32)>,
}

#[derive(Deserialize)]
pub struct Art {
    icons: HashMap<u32, u32>,
    pub legacy: Vec<LegacyTree>,
}

impl Art {
    pub fn icon(&self, spell_id: &str) -> Option<u32> {
        self.icons.get(&spell_id.trim().parse().ok()?).copied()
    }
}

pub fn art() -> &'static Art {
    static ART: OnceLock<Art> = OnceLock::new();
    ART.get_or_init(|| {
        serde_json::from_str(include_str!("../data/talent-art.json"))
            .expect("companion/data/talent-art.json is valid")
    })
}
